        float mask = smoothstep(0.014, 0.004, d);
        trailCol += vec3(1.0, 0.25, 0.15) * mask * weight;
    }
    col += trailCol;

    float hub = smoothstep(0.03, 0.02, rFace);
    col = mix(col, vec3(1.0, 0.3, 0.2), hub);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

